style.css:
@-moz-document domain("pinterest.com") {
/* --------------------------------------------------
       1. Warm Comic Palette & Fonts
       -------------------------------------------------- */
    :root {
        --snoopy-cream: #FAF6EE !important;
        --snoopy-yellow: #FCD116 !important;
        --snoopy-black: #1A1A1A !important;
        --snoopy-red: #E53935 !important;
        --snoopy-white: #FFFFFF !important;
        --snoopy-card-bg: #FFFDF9 !important;
        --snoopy-border: 2px solid #1A1A1A !important;
        --snoopy-font: 'Comic Sans MS', 'Comic Neue', cursive, sans-serif !important;
    }

    /* Apply global background and font */
    body, #__next, [data-test-id="app"], div {
        background-color: var(--snoopy-cream) !important;
        font-family: var(--snoopy-font) !important;
        color: var(--snoopy-black) !important;
    }

    /* --------------------------------------------------
       2. Top Navigation Bar
       -------------------------------------------------- */
    div[data-test-id="header-container"], 
    header, 
    nav {
        background-color: var(--snoopy-yellow) !important;
        border-bottom: var(--snoopy-border) !important;
        box-shadow: 0 4px 0px rgba(0,0,0,0.15) !important;
    }

    /* Replace Pinterest Logo with Snoopy Icon */
    a[aria-label="Home"], a[aria-label="Pinterest"] {
        background-image: url('https://img.icons8.com/color/96/snoopy.png') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
    }
    
    a[aria-label="Home"] svg, a[aria-label="Pinterest"] svg {
        display: none !important;
    }

    /* Search Bar Styling */
    div[data-test-id="search-box-input"], input {
        background-color: var(--snoopy-white) !important;
        border: 2px solid var(--snoopy-black) !important;
        border-radius: 20px !important;
        color: var(--snoopy-black) !important;
    }

    /* --------------------------------------------------
       3. Pin Cards & Board Styling
       -------------------------------------------------- */
    div[data-test-id="pin"], 
    div[data-test-id="card"] {
        background-color: var(--snoopy-card-bg) !important;
        border: 2px solid var(--snoopy-black) !important;
        border-radius: 16px !important;
        box-shadow: 4px 4px 0px #1A1A1A !important;
        transition: transform 0.2s ease, box-shadow 0.2s ease !important;
    }

    div[data-test-id="pin"]:hover, 
    div[data-test-id="card"]:hover {
        transform: translateY(-4px) !important;
        box-shadow: 6px 6px 0px #1A1A1A !important;
    }

    div[data-test-id="pin"] img {
        border-radius: 12px !important;
    }

    /* --------------------------------------------------
       4. Buttons & Actions
       -------------------------------------------------- */
    button, 
    div[role="button"] {
        border-radius: 20px !important;
        font-family: var(--snoopy-font) !important;
        font-weight: bold !important;
    }

    div[data-test-id="pin-save-button"] button,
    button[data-test-id="act-type-button"] {
        background-color: var(--snoopy-red) !important;
        color: var(--snoopy-white) !important;
        border: 2px solid var(--snoopy-black) !important;
        box-shadow: 2px 2px 0px #1A1A1A !important;
    }

    div[data-test-id="pin-save-button"] button:hover {
        background-color: #C62828 !important;
    }

    /* --------------------------------------------------
       5. Scrollbar Customization
       -------------------------------------------------- */
    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-track {
        background: var(--snoopy-cream);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--snoopy-yellow);
        border: 2px solid var(--snoopy-black);
        border-radius: 10px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: var(--snoopy-red);
    }
}
